const int NUM_CIRCLES = 6;
const vec2 BASE_CIRCLE_CENTERS[10] = vec2[10](vec2(889.904910, 340.651120), vec2(678.713921, 472.476808), vec2(833.847439, 858.133230), vec2(718.069772, 750.190591), vec2(514.073759, 280.580803), vec2(300.776614, 729.782296), vec2(110.243624, 7.308074), vec2(638.330575, 225.651338), vec2(697.497380, 479.077459), vec2(209.627662, 338.212717));
bool lineIntersection(vec2 a, vec2 b, vec2 c, vec2 d, out float r, out float s) {
    float denominator = (b.x-a.x)*(d.y-c.y) - (b.y-a.y)*(d.x-c.x);
    r = ((a.y-c.y)*(d.x-c.x) - (a.x-c.x)*(d.y-c.y))/denominator;
    s = ((a.y-c.y)*(b.x-a.x) - (a.x-c.y)*(b.y-a.y))/denominator;
    return r >= 0. && r <= 1. && s >= 0. && s <= 1.;
}
void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = fragCoord/iResolution.xy, circleCenters[NUM_CIRCLES];
    float modBase = 20000.;
    for (int retries = 0; retries < 5; retries++) {
        uv = vec2(sin(3.14/4.)*uv.x+1.4*cos(3.14*2.*0.2733)*uv.y, -0.2-0.2*cos(3.14*2.*0.09)*uv.x+sin(3.14/4.)*uv.y);
        for (int i = 0; i < 10; i++) {
            vec2 dxy = 20000.*vec2(uv.x, uv.x+(uv.y-0.42)*0.15);
            circleCenters[i] = BASE_CIRCLE_CENTERS[i] + vec2(mod(dxy.x, modBase), mod(dxy.y+1000.*(iTime+7.), 800.+0.));
        }
        float numIntersections = 0.;
        vec2 intersectionSum = vec2(0);
        vec2 stSum = vec2(0, 0);
        bool lineExists[NUM_CIRCLES*NUM_CIRCLES];
        for (int i = 0; i < NUM_CIRCLES; i++) {
            for (int j = i+1; j < NUM_CIRCLES; j++) {
                lineExists[i+NUM_CIRCLES*j] = true;
                for (int i2 = 0; i2 < i; i2++) {
                    for (int j2 = i2; j2 < NUM_CIRCLES; j2++) {
                        if (!lineExists[i2+NUM_CIRCLES*j2]) continue; 
                        float s, t;
                        if (lineIntersection(circleCenters[i], circleCenters[j], circleCenters[i2], circleCenters[j2], s, t)) {
                           intersectionSum += vec2(circleCenters[i].x + s * (circleCenters[j].x - circleCenters[i].x), circleCenters[i].y + s * (circleCenters[j].y - circleCenters[i].y));
                           numIntersections++;
                           stSum += vec2(s, t);
                           lineExists[i+NUM_CIRCLES*j] = false;
                           break;
                    }}
                    if (!lineExists[i+NUM_CIRCLES*j]) break;
        }}}
        fragColor = vec4(stSum.x/numIntersections, stSum.y/numIntersections, numIntersections/float(NUM_CIRCLES), 1.);
        if (numIntersections > 0.) return;
        uv = vec2(cos(3.14*0.25)*uv.x + sin(3.14*0.25)*uv.y, -sin(3.14*0.25)*uv.x + cos(3.14*0.25)*uv.y);
        modBase /= (3. + 0.3*(1.+sin(iTime/6.4*2.*3.14159265359)));
}}
